-- Mom's 70th (trip 6): itinerary review fixes, applied live 2026-09-16.
-- Arrival split (three by train, two with the car), car returned at Heathrow,
-- Monday rebuilt around the 3pm Airbnb check-in, Saturday walk untangled,
-- Wednesday lightened, Greenwich reordered, Kew at 10, dinner lists trimmed
-- to what can still be booked, Sunday options widened (NYT 36 Hours +
-- Cotswold Harry Potter locations).
begin;

-- ── Fri Oct 16: arrival ─────────────────────────────────────────────────────
insert into koji_stops (day_id, sort_order, time_label, tag, tag_color, title, body_md, is_optional)
select 57, 5, '8:30am', 'Travel', 'gray', 'Mom, Nathan & Dez: straight to Stroud',
$q$No three-hour wait at arrivals. Once through immigration (about 8:15), take the Heathrow Express to [Paddington](https://www.google.com/maps/search/?api=1&query=Paddington+Station+London) (15 minutes) and the direct GWR train to [Stroud](https://www.google.com/maps/search/?api=1&query=Stroud+Railway+Station) (about 1h20, roughly hourly), then a 10-minute taxi to the hotel ([01453 767878](tel:+441453767878)). Or pre-book a car from Heathrow to the hotel (about 1h45) and skip the changes. Either way you're at Burleigh Court by midday.$q$, false
where not exists (select 1 from koji_stops where day_id = 57 and title = 'Mom, Nathan & Dez: straight to Stroud');

update koji_stops set title = 'Marshall & Francesca: pick up the car', body_md = $q$Landing at 10:15, Marshall and Francesca collect the rental at a [Heathrow](https://www.google.com/maps/search/?api=1&query=Heathrow+Airport+car+rental) depot and drive west. About 1h45, and the route skips London. A standard five-seater is fine for the day trips: the car only carries luggage for two, since the others go by train both ways.$q$ where id = 177;

update koji_logistics set value_md = $q$Everyone lands Fri Oct 16 - Mom 7:10am (Delta), Nathan & Dez 7:15am (United), Marshall & Francesca 10:15am (Virgin Atlantic). The first three go straight on by Heathrow Express and the direct train to Stroud (or a pre-booked car), and are at the hotel by midday. Marshall and Francesca pick up the rental at Heathrow and drive (~1h45). On Monday the same split runs in reverse: three by train from Stroud, two returning the car at Heathrow and taking the Heathrow Express in.$q$ where id = 111;

-- ── Sat Oct 17: the walk ────────────────────────────────────────────────────
update koji_stops set time_label = '9am', body_md = $q$Saturday mornings from 9, 10 minutes from the hotel. Stroud's market is one of the largest farmers' markets in the country, with dozens of stalls of local produce. Breakfast from the stalls, and picnic supplies if lunch is to be on the green in Lower Slaughter, then drive north (about 50 minutes to Bourton). [Stroud Farmers' Market](https://www.google.com/maps/search/?api=1&query=Stroud+Farmers+Market).$q$ where id = 492;

update koji_stops set time_label = '10:15am', body_md = $q$5 to 6 miles, mostly flat, on a riverside path along the River Eye. Allow 3 hours with stops. Start in [Bourton-on-the-Water](https://www.google.com/maps/search/?api=1&query=Bourton-on-the-Water) and park at the Rissington Road car park. The loop runs Bourton to Lower Slaughter to Upper Slaughter and back to Bourton; the full self-guided route and the shorter version are in the Logistics tab.$q$ where id = 182;

update koji_stops set time_label = '11am', title = 'Coffee stop in Lower Slaughter', body_md = $q$About 1.5 miles in. [The Slaughters Country Inn](https://www.google.com/maps/search/?api=1&query=The+Slaughters+Country+Inn), a former manor house with a terrace on the River Eye, is open all day and needs no booking for drinks. Twenty minutes, then on to Upper Slaughter.$q$ where id = 183;

update koji_stops set time_label = '1:15pm', title = 'Lunch in Bourton', body_md = $q$The loop ends back in Bourton: [The Mousetrap Inn](https://www.google.com/maps/search/?api=1&query=The+Mousetrap+Inn+Bourton+on+the+Water) for a pub lunch (book for five on a Saturday). If the market provided a picnic, eat it on the green in Lower Slaughter instead and skip this.$q$ where id = 184;

update koji_stops set body_md = $q$Independent shops along [Black Jack Street](https://www.google.com/maps/search/?api=1&query=Black+Jack+Street+Cirencester) and [Cricklade Street](https://www.google.com/maps/search/?api=1&query=Cricklade+Street+Cirencester), both just off the Market Place. Tea or coffee at [Made by Bob](https://www.google.com/maps/search/?api=1&query=Made+by+Bob+Cirencester) or [Jack's Coffee](https://www.google.com/maps/search/?api=1&query=Jacks+Coffee+Cirencester) before the drive back; most cafés close by 5 on a Saturday.$q$ where id = 187;

update koji_stops set body_md = $q$**Closest to the hotel:** [The Bell at Sapperton](https://www.google.com/maps/search/?api=1&query=The+Bell+at+Sapperton), a village pub 10 minutes from Burleigh Court and 15 from Cirencester. *Reservation required.*<br><br>**Country house:** [The Wheatsheaf at Northleach](https://www.google.com/maps/search/?api=1&query=The+Wheatsheaf+Inn+Northleach), a coaching inn with a modern British menu and a fireplace; 20 minutes from Cirencester, 35 back to the hotel. *Reservation required.*<br><br>**Indian:** [Prithvi](https://www.google.com/maps/search/?api=1&query=Prithvi+Cheltenham) in Cheltenham, Michelin-starred, if the first night went to the hotel instead; 30 minutes from Cirencester. *Reservation required.*$q$ where id = 188;

-- ── Sun Oct 18: options widened (still to plan) ─────────────────────────────
update koji_stops set body_md = $q$An open Cotswolds day; everything below is within an hour of the hotel.<br><br>**Harry Potter, for Dez:** [Gloucester Cathedral](https://www.google.com/maps/search/?api=1&query=Gloucester+Cathedral) (25 minutes) is the Hogwarts corridors from the first three films, with fan-vaulted cloisters, and has choral evensong on Sunday afternoons (check the time). [Lacock Abbey](https://www.google.com/maps/search/?api=1&query=Lacock+Abbey+Wiltshire) (40 minutes, National Trust) is the Mirror of Erised room and more corridors, in a village that doubled as Budleigh Babberton and the Potters' Godric's Hollow house.<br><br>**Close by, from the NYT's 36 Hours:** the [Woolpack](https://www.google.com/maps/search/?api=1&query=The+Woolpack+Inn+Slad) in Slad (15 minutes) and the Laurie Lee Way up the valley, hilly and uneven; [Tetbury](https://www.google.com/maps/search/?api=1&query=Tetbury) (20 minutes) for breakfast at [Charlie's Cafe](https://www.google.com/maps/search/?api=1&query=Charlies+Cafe+and+Wine+Bar+Tetbury), [Top Banana Antiques](https://www.google.com/maps/search/?api=1&query=Top+Banana+Antiques+Tetbury), and [Highgrove Gardens](https://www.google.com/maps/search/?api=1&query=Highgrove+Gardens+Tetbury) tours if any dates remain (book weeks ahead); [Malmesbury Abbey](https://www.google.com/maps/search/?api=1&query=Malmesbury+Abbey) (25 minutes), burial place of Athelstan; afternoon tea at [Lords of the Manor](https://www.google.com/maps/search/?api=1&query=Lords+of+the+Manor+Upper+Slaughter) in Upper Slaughter; [Sudeley Castle](https://www.google.com/maps/search/?api=1&query=Sudeley+Castle+Winchcombe) (45 minutes), Katherine Parr's burial place with the finest gardens in the region; dinner at [Lardon](https://www.google.com/maps/search/?api=1&query=Lardon+Elkstone) in Elkstone, wood-fired cooking 25 minutes from the hotel.<br><br>**October colour:** [Westonbirt, the National Arboretum](https://www.google.com/maps/search/?api=1&query=Westonbirt+Arboretum) (20 minutes) at its peak in late October, and [Painswick Rococo Garden](https://www.google.com/maps/search/?api=1&query=Painswick+Rococo+Garden) (15 minutes).<br><br>**Further north:** [Broadway Tower](https://www.google.com/maps/search/?api=1&query=Broadway+Tower+Worcestershire), [Chipping Campden](https://www.google.com/maps/search/?api=1&query=Chipping+Campden) and [Hidcote](https://www.google.com/maps/search/?api=1&query=Hidcote+Manor+Garden), [Batsford Arboretum](https://www.google.com/maps/search/?api=1&query=Batsford+Arboretum+Moreton-in-Marsh), [Blenheim Palace](https://www.google.com/maps/search/?api=1&query=Blenheim+Palace+Woodstock), [Bibury](https://www.google.com/maps/search/?api=1&query=Bibury), all an hour or more each way.<br><br>Many village kitchens close on Sunday night, so book dinner ahead: [The Wild Rabbit](https://www.google.com/maps/search/?api=1&query=The+Wild+Rabbit+Kingham), [The Old Butcher's](https://www.google.com/maps/search/?api=1&query=The+Old+Butchers+Stow+on+the+Wold), Lardon, or the hotel.$q$ where id = 477;

-- ── Mon Oct 19: rebuilt around the 3pm check-in ─────────────────────────────
update koji_stops set sort_order = 10, time_label = '10:30am', body_md = $q$Check out. Mom, Nathan and Dez: taxi to [Stroud](https://www.google.com/maps/search/?api=1&query=Stroud+Railway+Station) and the direct train to [Paddington](https://www.google.com/maps/search/?api=1&query=Paddington+Station+London) (about 1h20). Marshall and Francesca: return the car at Heathrow, where it was collected, and take the Heathrow Express to Paddington (15 minutes). No driving in London. Everyone at Paddington by about 1pm; the flat is a 10-minute walk, but check-in is 3pm, so bags go to the left-luggage counter at Paddington or wait with lunch.$q$ where id = 488;

update koji_stops set sort_order = 20, time_label = '1:15pm', title = 'Lunch near the flat', body_md = $q$Somewhere within a few minutes of Lancaster Gate, with the bags: [The Victoria](https://www.google.com/maps/search/?api=1&query=The+Victoria+Strathearn+Place+London), a Fuller's pub on Strathearn Place, or the cafés around [Connaught Village](https://www.google.com/maps/search/?api=1&query=Connaught+Street+London).$q$ where id = 145;

update koji_stops set sort_order = 30, time_label = '3pm', body_md = $q$Check-in at the [Airbnb](https://www.google.com/maps/search/?api=1&query=Lancaster+Gate+Station+London) opens at 3pm (address and entry details in the Airbnb app). Unpack, tea, and leave together at 4:10: from Paddington the Circle or District line runs to St James's Park in about 10 minutes.$q$ where id = 147;

update koji_stops set sort_order = 40, time_label = '4:20pm', title = 'St James''s Park to the Abbey', body_md = $q$Out at [St James's Park](https://www.google.com/maps/search/?api=1&query=St+Jamess+Park+Station+London) station and through the park to the Abbey: October foliage, the lake, and the resident pelicans, which have lived here since a Russian ambassador gave the first ones to Charles II in 1664. Twenty minutes, arriving at the North Door by 4:40.$q$ where id = 146;

update koji_stops set sort_order = 50 where id = 148;
update koji_stops set sort_order = 60 where id = 149;

-- Hampstead moves to Thursday's split morning
update koji_stops set day_id = 54, sort_order = 25, time_label = '10am', title = 'Split: Hampstead village', body_md = $q$The third track for the morning. The Northern line runs to [Hampstead](https://www.google.com/maps/search/?api=1&query=Hampstead+London) in about 30 minutes from Lancaster Gate; the village sits on the hill above Hampstead Heath. Coffee at [Gail's](https://www.google.com/maps/search/?api=1&query=Gails+Bakery+Hampstead), the original branch, the [Antique & Craft Emporium](https://www.google.com/maps/search/?api=1&query=Hampstead+Antique+and+Craft+Emporium), and [St John-at-Hampstead](https://www.google.com/maps/search/?api=1&query=St+John+at+Hampstead+Church) and its churchyard, where John Constable is buried. Back down to Bloomsbury for 12:30 (25 minutes).$q$ where id = 493;

update koji_stops set body_md = $q$The other half of the morning split. [Imperial War Museum](https://www.google.com/maps/search/?api=1&query=Imperial+War+Museum+London) in Lambeth is free and open daily 10am-6pm. The [Churchill War Rooms](https://www.google.com/maps/search/?api=1&query=Churchill+War+Rooms+London), the underground bunker the war cabinet worked from, is the alternative (timed tickets; book ahead). Hampstead is the third option. Everyone meets at [The Lamb](https://www.google.com/maps/search/?api=1&query=The+Lamb+Lambs+Conduit+Street+London) for lunch at 12:30pm.$q$ where id = 484;

-- ── Tue Oct 20: Greenwich order, dinner list ────────────────────────────────
update koji_stops set sort_order = 40, time_label = '2pm' where id = 171;
update koji_stops set sort_order = 50, time_label = '3pm', body_md = $q$A 19th-century tea clipper, once the fastest ship on the China tea run, dry-docked next to the pier and open to walk through. 30 minutes, and easy to skip if anyone is tired. Placed before the Observatory so it isn't caught by the 4:15 last entry. [Cutty Sark](https://www.google.com/maps/search/?api=1&query=Cutty+Sark+Greenwich+London). The [National Maritime Museum](https://www.google.com/maps/search/?api=1&query=National+Maritime+Museum+Greenwich) (free) is the wet-weather alternative.$q$ where id = 174;
update koji_stops set sort_order = 60, time_label = '3:45pm', body_md = $q$The Prime Meridian runs through the courtyard; stand with a foot in each hemisphere. The walk up through [Greenwich Park](https://www.google.com/maps/search/?api=1&query=Greenwich+Park+London) takes about 10 minutes and is steep at the end; the top looks back over the river to the City. Closes at 5. [Royal Observatory Greenwich](https://www.google.com/maps/search/?api=1&query=Royal+Observatory+Greenwich+London).$q$ where id = 173;
update koji_stops set sort_order = 70, time_label = '5pm', body_md = $q$Same route back, in evening light; sunset is just before 6. The boat stops at Vauxhall on the way, which is the stop for Adulis.$q$ where id = 175;
update koji_stops set sort_order = 80, body_md = $q$**Fish and chips:** [The Golden Hind](https://www.google.com/maps/search/?api=1&query=The+Golden+Hind+Marylebone+London) in Marylebone, a chippy since 1914, bring your own bottle. *Walk-in fine.*<br><br>**Ethiopian:** [Adulis](https://www.google.com/maps/search/?api=1&query=Adulis+Restaurant+Vauxhall+London) in Vauxhall, Ethiopian and Eritrean platters served on injera and eaten by hand, which suits a table of five; get off the boat at Vauxhall. *Reservation recommended.*$q$ where id = 176;

-- ── Wed Oct 21: lighter day, Kew opens at 10 ────────────────────────────────
update koji_stops set time_label = '10am', body_md = $q$A UNESCO World Heritage site with the largest botanical collection in the world. 30 minutes by Tube from Lancaster Gate (Central line to Notting Hill Gate, then the District line to Kew Gardens). The [Palm House](https://www.google.com/maps/search/?api=1&query=Palm+House+Kew+Gardens) is a Victorian glasshouse from 1848, the [Temperate House](https://www.google.com/maps/search/?api=1&query=Temperate+House+Kew+Gardens) is the largest surviving Victorian glasshouse anywhere, and the [Treetop Walkway](https://www.google.com/maps/search/?api=1&query=Treetop+Walkway+Kew+Gardens) runs 18 metres up through the canopy. October means dahlias and autumn colour. Three hours from the 10am opening covers it; bring a layer. **Reservation recommended** for timed entry. [Kew Gardens](https://www.google.com/maps/search/?api=1&query=Kew+Gardens+London).$q$ where id = 164;
update koji_stops set time_label = '1pm' where id = 165;
update koji_stops set time_label = '2:30pm', is_optional = true, body_md = $q$Optional. Free, no tickets, and a straight run from Kew on the District line (about 25 minutes). The V&A holds the world's largest collection of decorative arts and design; the fashion and textile galleries connect to Saturday's Liberty stop, and the Cast Courts (full-size plaster casts of Trajan's Column and Michelangelo's David) and the jewellery rooms are the other rooms to see. An hour or two. Anyone who would rather rest goes straight back to the flat from Kew. [Victoria and Albert Museum](https://www.google.com/maps/search/?api=1&query=Victoria+and+Albert+Museum+London).$q$ where id = 491;
update koji_stops set time_label = '4pm', tag = 'Reset', tag_color = 'amber', title = 'Back to the flat', body_md = $q$An hour off at the flat. Notting Hill Gate is a 12-minute walk from Lancaster Gate along Bayswater Road or through [Kensington Gardens](https://www.google.com/maps/search/?api=1&query=Kensington+Gardens+London), so the evening starts from home.$q$ where id = 166;
update koji_stops set time_label = '5:15pm' where id = 167;
update koji_stops set time_label = '6:30pm', tag = 'Dinner', tag_color = 'sky', title = 'Dinner at The Churchill Arms', body_md = $q$A pub covered in flower baskets, named for Churchill, whose grandparents drank here, with a Thai kitchen in the back that has served food since 1988. Dinner is here unless the group wants one of the alternatives below; arrive by 6:30 for a table. [The Churchill Arms](https://www.google.com/maps/search/?api=1&query=The+Churchill+Arms+Notting+Hill+London). For a cocktail first, [Trailer Happiness](https://www.google.com/maps/search/?api=1&query=Trailer+Happiness+Portobello+London) down the road is a tiki bar.$q$ where id = 168;
update koji_stops set time_label = '7:30pm', is_optional = true, title = 'Dinner alternatives (African / Caribbean)', body_md = $q$**West African:** [Akoko](https://www.google.com/maps/search/?api=1&query=Akoko+Fitzrovia+London) in Fitzrovia, a Michelin-starred tasting menu built on West African cooking (smoked jollof, kelewele, suya); 20 minutes from Notting Hill. The expensive option. *Reservation required; ask now, it books 4+ weeks out.*<br><br>**Caribbean:** [Fish, Wings & Tings](https://www.google.com/maps/search/?api=1&query=Fish+Wings+and+Tings+Brixton+London) in Brixton Village, Trinidadian doubles, jerk wings, and curry goat roti at a counter; 35 minutes by Tube. *Walk-in fine.*$q$ where id = 169;

-- ── Thu Oct 22 ──────────────────────────────────────────────────────────────
update koji_stops set body_md = $q$Five minutes from Daunt. Afternoon tea in the glass-roofed courtyard of Hertford House, a 1776 townhouse holding the Wallace family's collection of 18th-century French art and armour. Less expensive than the Ritz or Claridge's. **Reservation required; book 4 weeks out**, and confirm a 4:30 sitting exists, since the museum closes at 5; if not, tea first at 3:30 and Daunt after. [The Wallace Collection](https://www.google.com/maps/search/?api=1&query=The+Wallace+Collection+London).$q$ where id = 162;

-- ── Fri Oct 23 ──────────────────────────────────────────────────────────────
update koji_stops set body_md = $q$A 15-minute walk from St Paul's. A Victorian arcade of iron and glass from 1881, on the site of the Roman forum; it stood in for Diagon Alley in the first Harry Potter film. 15 minutes. [Leadenhall Market](https://www.google.com/maps/search/?api=1&query=Leadenhall+Market+London).$q$ where id = 154;
update koji_stops set body_md = $q$Ten minutes' walk from Leadenhall. [Old Spitalfields Market](https://www.google.com/maps/search/?api=1&query=Old+Spitalfields+Market+London), the streets around [Brick Lane](https://www.google.com/maps/search/?api=1&query=Brick+Lane+London), vintage shops toward [Shoreditch](https://www.google.com/maps/search/?api=1&query=Shoreditch+London), or the free [Museum of the Home](https://www.google.com/maps/search/?api=1&query=Museum+of+the+Home+London) in Hoxton, set in 18th-century almshouses. Anyone who would rather have tea can peel off to [Fortnum & Mason](https://www.google.com/maps/search/?api=1&query=Fortnum+and+Mason+London), and anyone who would rather rest can go back to the flat (35 minutes from Liverpool Street); regroup for dinner at 7.$q$ where id = 155;
update koji_stops set body_md = $q$**British:** [St. John Bread and Wine](https://www.google.com/maps/search/?api=1&query=St+John+Bread+and+Wine+Spitalfields+London) in Spitalfields, Fergus Henderson's smaller restaurant: roast bone marrow, Welsh rarebit, Eccles cakes. *Reservation required; book now.*<br><br>**Fish and chips:** [Poppie's](https://www.google.com/maps/search/?api=1&query=Poppies+Fish+and+Chips+Spitalfields) in Spitalfields, a chippy done up like the 1950s. *Walk-in fine.*<br><br>**Indian:** [Brigadiers](https://www.google.com/maps/search/?api=1&query=Brigadiers+Restaurant+London) in the City, Indian barbecue in a room styled on an army mess, a few stops west on the way home. *Reservation required.*<br><br>Afterwards, a nightcap around Shoreditch for anyone still going.$q$ where id = 156;

-- ── Sat Oct 24 ──────────────────────────────────────────────────────────────
update koji_stops set body_md = $q$The Making of Harry Potter: the original sets, props, and costumes at [Warner Bros. Studio Tour London](https://www.google.com/maps/search/?api=1&query=Warner+Bros+Studio+Tour+London+Leavesden) in Leavesden, where all eight films were made. All five go. Leave the flat by 8:45: Tube or taxi to [Euston](https://www.google.com/maps/search/?api=1&query=London+Euston+Station), train to [Watford Junction](https://www.google.com/maps/search/?api=1&query=Watford+Junction+Station) (20 minutes), then the shuttle bus, to be there 20 minutes before the 10:30 slot. Plan on about 3.5 hours inside; lunch is in the studio café (butterbeer included). Back in town for Liberty at 4pm. **Timed tickets only; book now.** October Saturdays sell out.$q$ where id = 479;

-- ── Logistics ───────────────────────────────────────────────────────────────
update koji_logistics set value_md = $q$**Default rhythm:** late morning through dinner together; mornings flexible. **Group favorites:** markets, walks, parks, sacred music, high tea, pubs. **Built-in splits:** Thursday morning (Soane's, the war museums, or Hampstead), Wednesday's optional V&A, Tuesday's optional Cutty Sark, Saturday Oct 17's short or long Slaughters walk. Anyone can go back to the flat for an hour at any point; it is central to everything west of the City.$q$ where id = 35;

update koji_logistics set value_md = $q$[Westminster Abbey](https://www.google.com/maps/search/?api=1&query=Westminster+Abbey+London) and [St Paul's](https://www.google.com/maps/search/?api=1&query=St+Pauls+Cathedral+London) closed Sundays for sightseeing (both fall on weekdays). [Kew](https://www.google.com/maps/search/?api=1&query=Kew+Gardens+London) opens at 10. [Sir John Soane's](https://www.google.com/maps/search/?api=1&query=Sir+John+Soanes+Museum+London) closed Mon & Tue; the Thursday Oct 22 visit is fine. [Borough Market](https://www.google.com/maps/search/?api=1&query=Borough+Market+London) closed Sundays and quiet Mon-Tue; we go Friday. [Greenwich Market](https://www.google.com/maps/search/?api=1&query=Greenwich+Market+London) most stalls closed Mondays; we go Tuesday. [Cutty Sark](https://www.google.com/maps/search/?api=1&query=Cutty+Sark+Greenwich+London) last entry 4:15. Many Cotswolds village kitchens close Sunday night: book Sunday Oct 18 dinner ahead.$q$ where id = 33;

update koji_logistics set value_md = $q$[Westminster Abbey](https://www.google.com/maps/search/?api=1&query=Westminster+Abbey+London) timed entry · [Tower of London](https://www.google.com/maps/search/?api=1&query=Tower+of+London) 9am slot · [Warner Bros. Studio Tour](https://www.google.com/maps/search/?api=1&query=Warner+Bros+Studio+Tour+London+Leavesden) timed entry · [Wallace Collection](https://www.google.com/maps/search/?api=1&query=The+Wallace+Collection+London) afternoon tea · [Sketch](https://www.google.com/maps/search/?api=1&query=Sketch+Mayfair+London) · [St. John Bread and Wine](https://www.google.com/maps/search/?api=1&query=St+John+Bread+and+Wine+Spitalfields+London) · [Akoko](https://www.google.com/maps/search/?api=1&query=Akoko+Fitzrovia+London) (may already be full). All of these for a party of five, this week.$q$ where id = 36;

update koji_logistics set value_md = $q$[Guinea Grill](https://www.google.com/maps/search/?api=1&query=The+Guinea+Grill+Mayfair+London) · [Kricket Soho](https://www.google.com/maps/search/?api=1&query=Kricket+Soho+London) · [Brigadiers](https://www.google.com/maps/search/?api=1&query=Brigadiers+Restaurant+London) · [Trishna](https://www.google.com/maps/search/?api=1&query=Trishna+Marylebone+London) · [Adulis](https://www.google.com/maps/search/?api=1&query=Adulis+Restaurant+Vauxhall+London) · [Mousetrap Inn](https://www.google.com/maps/search/?api=1&query=The+Mousetrap+Inn+Bourton+on+the+Water) Saturday lunch · [Bell at Sapperton](https://www.google.com/maps/search/?api=1&query=The+Bell+at+Sapperton) · [Wheatsheaf Northleach](https://www.google.com/maps/search/?api=1&query=The+Wheatsheaf+Inn+Northleach) · [Prithvi](https://www.google.com/maps/search/?api=1&query=Prithvi+Cheltenham) · [Wild Rabbit](https://www.google.com/maps/search/?api=1&query=The+Wild+Rabbit+Kingham) · [Old Butcher's](https://www.google.com/maps/search/?api=1&query=The+Old+Butchers+Stow+on+the+Wold) · Burleigh Court dinner Friday$q$ where id = 37;

update koji_logistics set value_md = $q$Evensong (queue 20 min early) · [Churchill Arms](https://www.google.com/maps/search/?api=1&query=The+Churchill+Arms+Notting+Hill+London) · [Poppie's](https://www.google.com/maps/search/?api=1&query=Poppies+Fish+and+Chips+Spitalfields) · [Golden Hind](https://www.google.com/maps/search/?api=1&query=The+Golden+Hind+Marylebone+London) · [Fish, Wings & Tings](https://www.google.com/maps/search/?api=1&query=Fish+Wings+and+Tings+Brixton+London) · [Fortnum & Mason](https://www.google.com/maps/search/?api=1&query=Fortnum+and+Mason+London) lower tea room · [British Library](https://www.google.com/maps/search/?api=1&query=British+Library+London) Treasures Gallery · [Sir John Soane's](https://www.google.com/maps/search/?api=1&query=Sir+John+Soanes+Museum+London) · [V&A](https://www.google.com/maps/search/?api=1&query=Victoria+and+Albert+Museum+London)$q$ where id = 39;

insert into koji_logistics (trip_id, column_key, category, label, value_md, sort_order)
select 6, 'logistics', 'other', 'Getting around London',
$q$Tap a contactless card or phone on the Tube and buses; fares cap daily, and no Oyster card is needed. Heathrow Express runs Paddington to Heathrow every 15 minutes (15 minutes, cheaper booked ahead). The flat sits between Lancaster Gate (Central line) and Paddington (Circle, District, Bakerloo, Elizabeth line), so most of the itinerary is 15 to 25 minutes door to door. Black cabs take cards; Uber works.$q$, 5
where not exists (select 1 from koji_logistics where trip_id = 6 and label = 'Getting around London');

commit;
